	@Test
	void nestedTripleConstructorsRetainTheirOwnComponentPositions() {
		ValueExprTripleRef nested = new ValueExprTripleRef("nested", Var.of("nestedSubject"),
				Var.of("nestedPredicate"), Var.of("nestedObject"));
		Map<String, Integer> masks = positionMasksFor(new ValueExprTripleRef("outer", nested,
				Var.of("outerPredicate"), Var.of("outerObject")));

		assertThat(masks).containsEntry("nestedSubject", ValuePosition.SUBJECT)
				.containsEntry("nestedPredicate", ValuePosition.PREDICATE)
				.containsEntry("nestedObject", ValuePosition.OBJECT)
				.containsEntry("outerPredicate", ValuePosition.PREDICATE)
				.containsEntry("outerObject", ValuePosition.OBJECT);
	}

	private static Map<String, Integer> positionMasksFor(ValueExprTripleRef triple) {
		Extension extension = new Extension(new SingletonSet(), new ExtensionElem(triple, "result"));
		QueryRoot root = new QueryRoot(extension);
		return NativeValuePositionAnalysis.analyze(root).masksFor(root);
	}

	@Test
	void calendarWorkerDeclinesInlineIdsAndBindsAComputedValueWithoutInlining(@TempDir File directory)
			throws Exception {
		ValueStore store = new ValueStore(directory, new LmdbStoreConfig().setInlineLiterals(false));
		try {
			store.startTransaction(true);
			long date = store.storeValue(SimpleValueFactory.getInstance()
					.createLiteral("2024-03-05T10:20:30Z", CoreDatatype.XSD.DATETIME));
			store.commit();
			LmdbNativeValueCodec codec = new LmdbNativeValueCodec(store);
			NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
			when(source.nativeValueCodec()).thenReturn(codec);
			FunctionCall expression = new FunctionCall(new Year().getURI(), new Var("date"));
			NativeScalarPlan inline = NativeScalarPlan.create(expression, name -> 0,
					NativeScalarPlan.ResultKind.INLINE_ID, false, 0L, false, false);
			NativeScalarPlan computed = NativeScalarPlan.create(expression, name -> 0,
					NativeScalarPlan.ResultKind.VALUE, false, 0L, true, true);
			NativeScalarPlan.WorkerContext context = new NativeScalarPlan.WorkerContext(source, codec, null);
			assertThat(inline.bindInlineId(context)).isNull();
			LmdbNativeCompiledValue value = computed.bindValue(context);
			assertThat(value).isNotNull();
			assertThat(LmdbNativeValueCodec.toValue(value.evaluator.eval(reader(date))))
					.isEqualTo(SimpleValueFactory.getInstance().createLiteral("2024", CoreDatatype.XSD.INTEGER));
		} finally {
			store.close();
		}
	}

	@Test
	void workerBindingUsesTheWorkerCodecAndFrozenSlotResolver() {
		NativeLmdbQuerySource sourceA = mock(NativeLmdbQuerySource.class);
		NativeLmdbQuerySource sourceB = mock(NativeLmdbQuerySource.class);
		LmdbNativeValueCodec codecA = mock(LmdbNativeValueCodec.class);
		LmdbNativeValueCodec codecB = mock(LmdbNativeValueCodec.class);
		when(codecA.decode(42L, ValuePosition.NONE)).thenReturn(stringValue("worker-a"));
		when(codecB.decode(42L, ValuePosition.NONE)).thenReturn(stringValue("worker-b"));
		when(codecA.decodeAssured(42L, ValuePosition.NONE)).thenReturn(stringValue("worker-a"));
		when(codecB.decodeAssured(42L, ValuePosition.NONE)).thenReturn(stringValue("worker-b"));

		NativeScalarPlan plan = NativeScalarPlan.create(new Str(new Var("value")), name -> 0,
				NativeScalarPlan.ResultKind.VALUE, false, 1L, false, false);
		assertThat(plan).isNotNull();

		LmdbNativeCompiledValue workerA = plan.bindValue(new NativeScalarPlan.WorkerContext(sourceA, codecA, null));
		LmdbNativeCompiledValue workerB = plan.bindValue(new NativeScalarPlan.WorkerContext(sourceB, codecB, null));
		assertThat(workerA).isNotNull();
		assertThat(workerB).isNotNull();
		assertThat(workerA.evaluator.eval(reader(42L)).label()).isEqualTo("worker-a");
		assertThat(workerB.evaluator.eval(reader(42L)).label()).isEqualTo("worker-b");
		assertThat(plan.slotMapping()).containsExactly(Map.entry("value", 0));
	}

