	@Test
	void planOwnsExpressionAndSlotMapping() {
		MathExpr expression = new MathExpr(new Var("value"), new ValueConstant(literal("1")),
				MathExpr.MathOp.PLUS);
		NativeScalarPlan plan = NativeScalarPlan.create(expression, name -> 3, NativeScalarPlan.ResultKind.VALUE,
				true, 1L << 3, false, false);
		assertThat(plan).isNotNull();

		expression.setOperator(MathExpr.MathOp.MINUS);
		assertThat(plan.expression()).isInstanceOf(MathExpr.class);
		assertThat(((MathExpr) plan.expression()).getOperator()).isEqualTo(MathExpr.MathOp.PLUS);
		assertThat(plan.dependencyMask()).isEqualTo(1L << 3);
		assertThat(plan.assuredMask()).isEqualTo(1L << 3);
		assertThatThrownBy(() -> plan.slotMapping().put("other", 4))
				.isInstanceOf(UnsupportedOperationException.class);
	}

	@Test
	void semanticEquivalenceUsesBoundSlotsAndConstants() {
		NativeScalarPlan leftAlias = NativeScalarPlan.create(new Str(new Var("left")), name -> 2,
				NativeScalarPlan.ResultKind.VALUE, false, 0L, false, false);
		NativeScalarPlan rightAlias = NativeScalarPlan.create(new Str(new Var("right")), name -> 2,
				NativeScalarPlan.ResultKind.VALUE, false, 0L, false, false);
		NativeScalarPlan differentConstant = NativeScalarPlan.create(new ValueConstant(literal("other")), name -> -1,
				NativeScalarPlan.ResultKind.VALUE, false, 0L, false, false);
		NativeScalarPlan firstConstant = NativeScalarPlan.create(new ValueConstant(literal("same")), name -> -1,
				NativeScalarPlan.ResultKind.VALUE, false, 0L, false, false);
		NativeScalarPlan secondConstant = NativeScalarPlan.create(new ValueConstant(literal("same")), name -> -1,
				NativeScalarPlan.ResultKind.VALUE, false, 0L, false, false);

		assertThat(leftAlias).isEqualTo(rightAlias);
		assertThat(leftAlias.hashCode()).isEqualTo(rightAlias.hashCode());
		assertThat(firstConstant).isEqualTo(secondConstant);
		assertThat(firstConstant).isNotEqualTo(differentConstant);
	}

	@Test
	void semanticKeyRetainsIriBaseAndTripleComponentRole() {
		IRIFunction baseOne = new IRIFunction(new Var("value"));
		baseOne.setBaseURI("https://example.com/one/");
		IRIFunction baseTwo = new IRIFunction(new Var("value"));
		baseTwo.setBaseURI("https://example.com/two/");
		NativeScalarPlan subject = planOf(new TripleComponent(new Var("triple"), TripleComponent.Role.SUBJECT));
		NativeScalarPlan object = planOf(new TripleComponent(new Var("triple"), TripleComponent.Role.OBJECT));

		assertThat(planOf(baseOne)).isNotEqualTo(planOf(baseTwo));
		assertThat(subject).isNotEqualTo(object);
	}

