	@Test
	void effectsJoinAcrossNestedExpressionsAndRespectBNodeIdentity() {
		assertThat(planOf(new Str(new Var("value"))).effect()).isEqualTo(EffectClass.PURE);
		assertThat(planOf(new FunctionCall(LmdbNativeFunctionLibrary.NOW_URI)).effect())
				.isEqualTo(EffectClass.QUERY_STABLE);
		assertThat(planOf(new BNodeGenerator(new ValueConstant(literal("label")))).effect())
				.isEqualTo(EffectClass.ROW_STABLE);
		assertThat(planOf(new BNodeGenerator()).effect()).isEqualTo(EffectClass.VOLATILE);
		assertThat(planOf(new FunctionCall("urn:rdf4j:test:unknown-function")).effect())
				.isEqualTo(EffectClass.SIDE_EFFECTING_OR_UNSUPPORTED);
		assertThat(
				planOf(new FunctionCall("urn:rdf4j:test:unknown-function", new Str(new Var("value")))).workerBindable())
						.isFalse();
		assertThat(planOf(new FunctionCall(org.eclipse.rdf4j.model.vocabulary.FN.LOWER_CASE.stringValue(),
				new FunctionCall(new Rand().getURI()))).effect()).isEqualTo(EffectClass.VOLATILE);
	}

	@Test
	void queryStableReuseRequiresAnExplicitlyPropagatedScopeWhenItReadsRows() {
		NativeScalarPlan plan = planOf(new FunctionCall(LmdbNativeFunctionLibrary.NOW_URI, new Var("value")));

		assertThat(plan.effect()).isEqualTo(EffectClass.QUERY_STABLE);
		assertThat(plan.canReuseAcrossSolutions()).isFalse();
		assertThat(plan.canReuseAcrossSolutions(false)).isFalse();
		assertThat(plan.canReuseAcrossSolutions(true)).isTrue();
		assertThat(plan.queryStableAtInput()).isFalse();
	}

